      SUBROUTINE WAISTCC     PRINTS LOCATION OF BEAM WAISTS IN BOTH TRANSVERSE PLANESC      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM15B.CIN'      INCLUDE 'ELM15C.CIN'      INCLUDE 'IOUNIT.CIN'C----------------------------------------------------------------------      CHARACTER*4     IPOS, IUP, IDOWN      DATA            IUP /'  UP'/, IDOWN /'DOWN'/CC     HORIZONTAL PLANEC      IF (.NOT. RECENT) CALL BEAM      SIT11 = SIT(1,1)      SIT12 = SIT(1,2)      SIT22 = SIT(2,2)      IF (SIT22 .LE. 0.0) GO TO 50      ADIFF = - SIT12/(SIT22*UNITO(8))      IF (ADIFF .LT. 0.0) IPOS = IUP      IF (ADIFF .GE. 0.0) IPOS = IDOWN      ALONG = LC/UFLOOR(1) + ADIFF      ADIFF = ABS(ADIFF)      XSIZE = (SIT11 - SIT12**2/SIT22)      IF (ACCEL) THEN        XSIZE = XSIZE*UNITO(2)/UNITO(1)        WRITE (NOUT,1004) XSIZE, ADIFF, XDIME(8), IPOS, ALONG, XFLOOR(1) 1004   FORMAT (1H ,32X,4HBETA,F8.3,1X,16HHORIZONTAL WAIST,F10.3,1X,A4,     1          1X,A4,9HSTREAM AT,F10.3,1X,A4)      ELSE        XSIZE = SQRT(XSIZE)/UNITO(1)        WRITE (NOUT,1002) XSIZE, XDIME(1), ADIFF, XDIME(8), IPOS, ALONG,     1                    XDIME(8) 1002   FORMAT (1H ,32X,F8.3,1X,A4,1X,16HHORIZONTAL WAIST,F10.3,1X,A4,     1          1X,A4,9HSTREAM AT,F10.3,1X,A4)      ENDIFCC     VERTICAL PLANEC   50 SIT33 = SIT(3,3)      SIT34 = SIT(3,4)      SIT44 = SIT(4,4)      IF (SIT44 .EQ. 0.0) GO TO 100      ADIFF = - SIT34/(SIT44*UFLOOR(1))      IF (ADIFF .LT. 0.0) IPOS = IUP      IF (ADIFF .GE. 0.0) IPOS = IDOWN      ALONG = LC/UFLOOR(1) + ADIFF      ADIFF = ABS(ADIFF)      YSIZE = (SIT33 - SIT34**2/SIT44)      IF (ACCEL) THEN        YSIZE = YSIZE*UNITO(4)/UNITO(3)        WRITE (NOUT,1005) YSIZE, ADIFF, XDIME(8), IPOS, ALONG, XFLOOR(1)      ELSE        YSIZE = SQRT(YSIZE)/UNITO(3)        WRITE (NOUT,1003) YSIZE, XDIME(1), ADIFF, XDIME(8), IPOS, ALONG,     1                    XDIME(8)      ENDIF 1003 FORMAT (1H ,32X,F8.3,1X,A4,1X,16H  VERTICAL WAIST,F10.3,1X,A4,1X,     1        A4,9HSTREAM AT,F10.3,1X,A4) 1005 FORMAT (1H ,32X,4HBETA,F8.3,1X,16H  VERTICAL WAIST,F10.3,1X,A4,     1        1X,A4,9HSTREAM AT,F10.3,1X,A4)C  100 RETURN      END